"use client"

import { Computer, MoonStar, PanelTop, Sun } from "lucide-react"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { useDisplayTheme, type DisplayTheme } from "@/hooks/use-display-theme"
import { cn } from "@/lib/utils"

const styles=`
.wlkr-footer-controls{display:inline-flex;align-items:center;gap:8px;color:var(--muted-foreground,#696969)}
.wlkr-footer-controls [data-slot=toggle-group]{display:inline-flex;gap:3px;padding:0;background:none;border:0;border-radius:0;box-shadow:none}
.wlkr-footer-controls [data-slot=toggle-group-item],.wlkr-footer-agent{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:0;border:0;border-radius:3px;box-shadow:none;background:transparent;color:inherit;cursor:pointer;text-decoration:none}
.wlkr-footer-controls [data-slot=toggle-group-item][data-state=on]{background:var(--muted,#f3f3f3);color:var(--foreground,#010101)}
.wlkr-footer-controls [data-slot=toggle-group-item]:focus-visible,.wlkr-footer-agent:focus-visible{outline:2px solid var(--ring,currentColor);outline-offset:4px}
.wlkr-footer-controls svg{width:17px;height:17px}
.wlkr-footer-agent:hover{color:var(--foreground,currentColor)}
`
/** System/light/dark display preferences and an actual app-owned Markdown/plain-text destination. */
export function FooterControls({agentHref,className,storageKey="wlkr-theme"}:{agentHref:string;className?:string;storageKey?:string}) {
  const {mode,setMode}=useDisplayTheme(storageKey)
  return <div className={cn("wlkr-footer-controls",className)}><style>{styles}</style><ToggleGroup type="single" value={mode} onValueChange={value=>{if(value)setMode(value as DisplayTheme)}} aria-label="Color theme">
    <ToggleGroupItem value="system" aria-label="System theme" title="System theme"><Computer aria-hidden="true"/></ToggleGroupItem>
    <ToggleGroupItem value="light" aria-label="Light theme" title="Light theme"><Sun aria-hidden="true"/></ToggleGroupItem>
    <ToggleGroupItem value="dark" aria-label="Dark theme" title="Dark theme"><MoonStar aria-hidden="true"/></ToggleGroupItem>
  </ToggleGroup><a className="wlkr-footer-agent" href={agentHref} target="_blank" rel="noopener noreferrer" aria-label="View as agent" title="View as agent"><PanelTop aria-hidden="true"/></a></div>
}

"use client"

import * as React from "react"

export type DisplayTheme = "system" | "light" | "dark"
const eventName="wlkr-theme-change"

/** One persisted preference shared by basic and footer controls; no provider or runtime package. */
export function useDisplayTheme(storageKey="wlkr-theme") {
  const memory=React.useRef<{value:DisplayTheme;override:boolean;key:string}>({value:"system",override:false,key:storageKey})
  const [state,setState]=React.useState<{mode:DisplayTheme;dark:boolean|null}>({mode:"system",dark:null})
  React.useEffect(()=>{
    if(memory.current.key!==storageKey)memory.current={value:"system",override:false,key:storageKey}
    const preference=window.matchMedia("(prefers-color-scheme: dark)")
    function sync(){
      let selected:string|null=memory.current.value
      if(!memory.current.override)try{selected=localStorage.getItem(storageKey)}catch{/* In-memory selection works when browser storage is blocked. */}
      const mode:DisplayTheme=selected==="light"||selected==="dark"?selected:"system"
      const dark=mode==="dark"||mode==="system"&&preference.matches
      document.documentElement.classList.toggle("dark",dark)
      document.documentElement.style.colorScheme=dark?"dark":"light"
      setState({mode,dark})
    }
    function storage(event:StorageEvent){if(event.key===storageKey||event.key===null){const value=event.newValue;memory.current={value:value==="dark"||value==="light"?value:"system",override:true,key:storageKey};sync()}}
    function shared(event:Event){const detail=(event as CustomEvent<{key:string;value:DisplayTheme}>).detail;if(detail?.key===storageKey){memory.current={value:detail.value,override:true,key:storageKey};sync()}}
    sync();window.addEventListener(eventName,shared);window.addEventListener("storage",storage);preference.addEventListener("change",sync)
    return()=>{window.removeEventListener(eventName,shared);window.removeEventListener("storage",storage);preference.removeEventListener("change",sync)}
  },[storageKey])
  function setMode(mode:DisplayTheme){
    memory.current={value:mode,override:true,key:storageKey}
    try{if(mode==="system")localStorage.removeItem(storageKey);else localStorage.setItem(storageKey,mode)}catch{/* Keep the current selection in memory without requiring browser storage. */}
    const dark=mode==="dark"||mode==="system"&&window.matchMedia("(prefers-color-scheme: dark)").matches
    document.documentElement.classList.toggle("dark",dark);document.documentElement.style.colorScheme=dark?"dark":"light";setState({mode,dark})
    window.dispatchEvent(new CustomEvent(eventName,{detail:{key:storageKey,value:mode}}))
  }
  return {...state,setMode}
}
